using System;using System.Collections;using System.Drawing;using System.Windows.Forms;using QuanLyBanDienThoai.BUS;using QuanLyBanDienThoai.DTO;
namespace QuanLyBanDienThoai.GUI { public class FormKhachHang:Form {
 readonly KhachHangBUS bus=new KhachHangBUS();readonly DataGridView grid=new DataGridView();readonly FlowLayoutPanel fields=new FlowLayoutPanel();readonly TextBox search=new TextBox();readonly System.Collections.Generic.Dictionary<string,Control> inputs=new System.Collections.Generic.Dictionary<string,Control>();
 public FormKhachHang(){Text="Quản lý KhachHang";Width=1000;Height=700;var top=new FlowLayoutPanel{Dock=DockStyle.Top,Height=80};top.Controls.Add(new Label{Text="Tìm kiếm",AutoSize=true,Padding=new Padding(5,10,0,0)});search.Width=180;top.Controls.Add(search);search.TextChanged+=(s,e)=>LoadGrid(search.Text);foreach(string name in new[]{"Thêm","Sửa","Xóa","Làm mới"}){var b=new Button{Text=name,Width=90};top.Controls.Add(b);b.Click+=(s,e)=>Action(name);}var advanced=new Button{Text="Tìm nâng cao",Width=120};top.Controls.Add(advanced);advanced.Click+=(s,e)=>{try{using(var f=new FormTimNangCao(typeof(KhachHang))){if(f.ShowDialog()==DialogResult.OK) grid.DataSource=bus.TimNangCao(f.KetQua);}}catch(Exception ex){MessageBox.Show(ex.Message);}};
 var export=new Button{Text="Xuất Excel",Width=100};top.Controls.Add(export);export.Click+=(s,e)=>{try{ExcelHelper.XuatCoHopThoai(bus.GetAll(),typeof(KhachHang),"KhachHang");}catch(Exception ex){MessageBox.Show(ex.Message);}};
 var import=new Button{Text="Nhập Excel",Width=100};top.Controls.Add(import);import.Click+=(s,e)=>{try{var list=ExcelHelper.NhapCoHopThoai(typeof(KhachHang));if(list==null)return;string errors=bus.NhapDanhSach(list,out int n);MessageBox.Show("Đã nhập "+n+" dòng.\n"+errors);LoadGrid("");}catch(Exception ex){MessageBox.Show(ex.Message);}};Controls.Add(top);
 fields.Dock=DockStyle.Top;fields.Height=175;fields.AutoScroll=true;fields.WrapContents=true;
 foreach(string name in new string[]{"Ho","Ten","SDT","Email","DiaChi","NgaySinh"}){var box=new Panel{Width=225,Height=53};box.Controls.Add(new Label{Text=name,Dock=DockStyle.Top});var t=new TextBox{Dock=DockStyle.Bottom,Width=200};if(name=="DiemTichLuy")t.ReadOnly=true;box.Controls.Add(t);fields.Controls.Add(box);inputs[name]=t;}Controls.Add(fields);
 grid.Dock=DockStyle.Fill;grid.ReadOnly=true;grid.AutoGenerateColumns=true;grid.SelectionMode=DataGridViewSelectionMode.FullRowSelect;grid.MultiSelect=false;grid.AllowUserToAddRows=false;grid.SelectionChanged+=(s,e)=>Fill();Controls.Add(grid);grid.BringToFront();fields.BringToFront();top.BringToFront();LoadGrid("");}
 void LoadGrid(string q){try{grid.DataSource=null;grid.DataSource=q.Length==0?bus.GetAll():bus.TimKiem(q);}catch(Exception e){MessageBox.Show(e.Message);}}
 void Fill(){if(grid.CurrentRow?.DataBoundItem is not KhachHang x)return;foreach(var pair in inputs){var prop=typeof(KhachHang).GetProperty(pair.Key);var val=prop?.GetValue(x);pair.Value.Text=val is DateTime d?d.ToString("yyyy-MM-dd"):Convert.ToString(val);}}
 void Action(string name){if(name=="Làm mới"){foreach(var t in inputs.Values)t.Text="";LoadGrid("");return;}try{var x=new KhachHang();if(name!="Thêm" && grid.CurrentRow?.DataBoundItem is KhachHang old)x.MaKH=old.MaKH;foreach(var pair in inputs){var prop=typeof(KhachHang).GetProperty(pair.Key);var t=Nullable.GetUnderlyingType(prop.PropertyType)??prop.PropertyType;object v;if(t==typeof(DateTime))v=string.IsNullOrWhiteSpace(pair.Value.Text)?null:DateTime.Parse(pair.Value.Text);else if(t==typeof(decimal))v=decimal.Parse(pair.Value.Text);else v=pair.Value.Text;prop.SetValue(x,v);}
 string err=name=="Thêm"?bus.Them(x):name=="Sửa"?bus.Sua(x):bus.Xoa(x.MaKH);if(err!="")MessageBox.Show(err);else LoadGrid("");}catch(Exception e){MessageBox.Show("Dữ liệu không hợp lệ: "+e.Message);}}
 } }